# Preserve logical numbering after replacement of former unnumbered exceptions.
for item in B:
 for unit in item['changes']:
  if (unit['file'],unit['article'])==('145','36'):
   lines=unit['new'].splitlines()
   exception=[x for x in lines if x.startswith('Исключение: При отсутствии лица')]
   assert len(exception)==1
   unit['new']='\n'.join(x for x in lines if x not in exception)+'\n'+exception[0].replace('Исключение: ', 'Часть 4. ',1)
  if (unit['file'],unit['article'])==('158','5'):
   unit['new']=unit['new'].replace('п) сотрудники подразделения Military Police', 'о) сотрудники подразделения Military Police').replace('о) Руководящий состав', 'п) Руководящий состав')

